using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text.Json;
public static class MacInstallCore {
 public static string Digest(string file){using(var s=File.OpenRead(file))return Convert.ToHexString(SHA256.HashData(s)).ToLowerInvariant();}
 public static string SafePath(string root,string relative){if(String.IsNullOrWhiteSpace(relative)||Path.IsPathRooted(relative)||relative.Split('/','\\').Any(x=>x==".."))throw new Exception("安装包路径无效。");string p=Path.GetFullPath(Path.Combine(root,relative));if(!p.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.Ordinal))throw new Exception("安装路径越界。");return p;}
 public static void Verify(string payload){var expected=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(payload,"integrity.json")));foreach(var f in expected)if(Digest(SafePath(payload,f.Key))!=f.Value)throw new Exception("安装包校验失败："+f.Key);}
 static void RejectLinks(string path){var d=new DirectoryInfo(Path.GetDirectoryName(Path.GetFullPath(path)));while(d!=null){if(d.Exists&&d.LinkTarget!=null)throw new Exception("安装位置包含链接，请使用默认用户目录。");d=d.Parent;}}
 public static void Install(string engine,string extension,string target,string browsers,bool includeBrowser,Action validate){
  var jobs=Path.Combine(target,"native/data/jobs");if(Directory.Exists(jobs))foreach(var p in Directory.GetFiles(jobs,"*.json")){using(var d=JsonDocument.Parse(File.ReadAllText(p))){var r=d.RootElement;if(r.TryGetProperty("status",out var st)&&new[]{"running","queued"}.Contains(st.GetString())&&r.TryGetProperty("pid",out var pid)){try{if(!Process.GetProcessById(pid.GetInt32()).HasExited)throw new InvalidOperationException("下载任务仍在运行，请完成任务后安装。");}catch(ArgumentException){}}}}
  var changes=new List<(string target,string backup,bool existed)>();string backupRoot=Path.Combine(target,"backups/mac-"+DateTime.UtcNow.ToString("yyyyMMddHHmmss")+"-"+Guid.NewGuid().ToString("N"));
  void Put(string from,string to,string text=null){RejectLinks(to);if(File.Exists(to)&&new FileInfo(to).LinkTarget!=null)throw new Exception("安装目标包含链接。");Directory.CreateDirectory(Path.GetDirectoryName(to));bool existed=File.Exists(to);string backup=Path.Combine(backupRoot,changes.Count.ToString()+".bak");if(existed){Directory.CreateDirectory(backupRoot);File.Copy(to,backup);}changes.Add((to,backup,existed));string tmp=to+".qingcun-install";try{if(text==null)File.Copy(from,tmp,true);else File.WriteAllText(tmp,text,new UTF8Encoding(false));File.Move(tmp,to,true);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
  void Tree(string from,string into){foreach(var file in Directory.GetFiles(from,"*",SearchOption.AllDirectories)){string rel=Path.GetRelativePath(from,file);if(rel.Split(Path.DirectorySeparatorChar).Any(s=>s=="data"||s=="backups"))throw new Exception("分发包包含个人数据。");Put(file,SafePath(into,rel));}}
  try{Tree(engine,Path.Combine(target,"native"));if(includeBrowser){Tree(extension,Path.Combine(target,"extension"));var manifest=JsonSerializer.Serialize(new{ name="com.qingcun.video_downloader",description="轻存视频下载组件",path=Path.Combine(target,"native/QingcunHost"),type="stdio",allowed_origins=new[]{"chrome-extension://ikbihjphodgkkollcgcocjibbgkehldo/"}});foreach(var vendor in new[]{"Google/Chrome","Microsoft Edge"})Put(null,Path.Combine(browsers,vendor,"NativeMessagingHosts/com.qingcun.video_downloader.json"),manifest);}
   if(OperatingSystem.IsMacOS()){var n=Path.Combine(target,"native");foreach(var file in Directory.GetFiles(n,"*",SearchOption.AllDirectories)){if(Path.GetRelativePath(n,file).Split('/')[0]=="data")continue;if(Path.GetExtension(file)==""||file.EndsWith(".dylib"))File.SetUnixFileMode(file,UnixFileMode.UserRead|UnixFileMode.UserWrite|UnixFileMode.UserExecute|UnixFileMode.GroupRead|UnixFileMode.GroupExecute|UnixFileMode.OtherRead|UnixFileMode.OtherExecute);}Directory.CreateDirectory(Path.Combine(n,"data"));File.SetUnixFileMode(Path.Combine(n,"data"),UnixFileMode.UserRead|UnixFileMode.UserWrite|UnixFileMode.UserExecute);}
   validate();
  }catch{foreach(var c in changes.AsEnumerable().Reverse()){if(c.existed)File.Copy(c.backup,c.target,true);else if(File.Exists(c.target))File.Delete(c.target);}throw;}
 }
 public static void CheckEngine(string host){var p=new ProcessStartInfo(host,"--mac-self-test"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true};using(var child=Process.Start(p)){var output=child.StandardOutput.ReadToEndAsync();var error=child.StandardError.ReadToEndAsync();if(!child.WaitForExit(60000)){child.Kill(true);throw new Exception("组件测试超时。");}System.Threading.Tasks.Task.WaitAll(output,error);if(child.ExitCode!=0)throw new Exception("组件无法运行（退出码 "+child.ExitCode+"），请保留安装日志："+error.Result);using(var json=JsonDocument.Parse(output.Result)){if(!json.RootElement.GetProperty("ok").GetBoolean())throw new Exception("组件检查失败。");}}}
}
partial class Host {
 static int MacSelfTest(){try{foreach(string name in new[]{"yt-dlp","ffmpeg","deno"}){Console.Error.WriteLine("[self-test] 正在检查 "+name);RunTool(Path.Combine(Root,"tools",ExecutableName(name)),new[]{name=="ffmpeg"?"-version":"--version"},15000);Console.Error.WriteLine("[self-test] "+name+" 正常");}Console.WriteLine("{\"ok\":true,\"version\":\"2.3.3\"}");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static int MacInstall(string payload,string resources,bool browser){try{if(!OperatingSystem.IsMacOS())throw new Exception("此安装器仅用于 Mac。");Console.Error.WriteLine("[install] 核对解压文件");MacInstallCore.Verify(payload);var target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Library/Application Support/QingcunVideo");Console.Error.WriteLine("[install] 检查下载组件");MacInstallCore.CheckEngine(Path.Combine(Root,"QingcunHost"));Console.Error.WriteLine("[install] 写入程序文件");MacInstallCore.Install(Root,Path.Combine(payload,"extension"),target,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Library/Application Support"),browser,()=>MacInstallCore.CheckEngine(Path.Combine(target,"native/QingcunHost")));string guide=Path.Combine(target,"安装说明.html");File.Copy(Path.Combine(resources,"安装说明.html"),guide,true);Console.Error.WriteLine("[install] 打开 Eagle 安装提示");MacOpen(Path.Combine(resources,"轻存-Eagle-v2.3.3-Mac.eagleplugin"));MacOpen(guide);if(browser)MacOpen(Path.Combine(target,"extension"));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
